-- Longe & Perto — Onda 4: campanhas codificadas (zero spoiler), RPCs de fuga e catálogo.
-- Migração idempotente: pode ser executada novamente sem duplicar dados.

------------------------------------------------------------------------------
-- 1) Tabela jogos_campanhas_segredo (sem policy pública: acesso só via RPC)
------------------------------------------------------------------------------
create table if not exists public.jogos_campanhas_segredo (
  id        text primary key,
  jogo_id   text not null check (jogo_id in ('aventura-a-dois', 'sala-de-fuga')),
  payload   jsonb not null,
  criado_em timestamptz not null default now()
);

alter table public.jogos_campanhas_segredo enable row level security;
-- Nenhuma policy para anon/authenticated: leitura exclusiva pelas RPCs abaixo.

------------------------------------------------------------------------------
-- 2) RPCs security definer
------------------------------------------------------------------------------
create or replace function public.jogo_aventura_carregar(
  p_campanha_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payload jsonb;
begin
  select c.payload
  into v_payload
  from public.jogos_campanhas_segredo c
  where c.id = p_campanha_id
    and c.jogo_id = 'aventura-a-dois';

  if v_payload is null then
    raise exception 'História não encontrada.';
  end if;

  return v_payload;
end;
$$;

create or replace function public.jogo_fuga_obter_etapa(
  p_sala_codigo text,
  p_partida_id  uuid,
  p_campanha_id text,
  p_etapa       integer,
  p_papel       text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payload jsonb;
  v_etapas  jsonb;
  v_total   integer;
  v_etapa   jsonb;
  v_papel   text := case when p_papel = 'manual' then 'manual' else 'painel' end;
begin
  if not exists (
    select 1
    from public.jogos_partidas p
    where p.id = p_partida_id
      and p.sala_codigo = p_sala_codigo
  ) then
    raise exception 'Partida não encontrada para esta sala.';
  end if;

  select c.payload
  into v_payload
  from public.jogos_campanhas_segredo c
  where c.id = p_campanha_id
    and c.jogo_id = 'sala-de-fuga';

  if v_payload is null then
    raise exception 'Sala de fuga não encontrada.';
  end if;

  v_etapas := coalesce(v_payload->'etapas', '[]'::jsonb);
  v_total := jsonb_array_length(v_etapas);

  select e
  into v_etapa
  from jsonb_array_elements(v_etapas) e
  where (e->>'etapa')::integer = p_etapa
  limit 1;

  if v_etapa is null then
    raise exception 'Etapa não encontrada.';
  end if;

  return jsonb_build_object(
    'etapa', p_etapa,
    'total_etapas', v_total,
    'titulo', coalesce(v_etapa->>'titulo', ''),
    'contexto', coalesce(v_etapa->>'contexto', ''),
    'papel', v_papel,
    'conteudo', coalesce(v_etapa->v_papel, '{}'::jsonb)
  );
end;
$$;

create or replace function public.jogo_fuga_validar_trava(
  p_sala_codigo text,
  p_partida_id  uuid,
  p_campanha_id text,
  p_etapa       integer,
  p_resposta    jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payload jsonb;
  v_etapas  jsonb;
  v_total   integer;
  v_etapa   jsonb;
  v_sol     jsonb;
  v_ok      boolean := false;
begin
  if not exists (
    select 1
    from public.jogos_partidas p
    where p.id = p_partida_id
      and p.sala_codigo = p_sala_codigo
  ) then
    raise exception 'Partida não encontrada para esta sala.';
  end if;

  select c.payload
  into v_payload
  from public.jogos_campanhas_segredo c
  where c.id = p_campanha_id
    and c.jogo_id = 'sala-de-fuga';

  if v_payload is null then
    raise exception 'Sala de fuga não encontrada.';
  end if;

  v_etapas := coalesce(v_payload->'etapas', '[]'::jsonb);
  v_total := jsonb_array_length(v_etapas);

  select e
  into v_etapa
  from jsonb_array_elements(v_etapas) e
  where (e->>'etapa')::integer = p_etapa
  limit 1;

  if v_etapa is null then
    raise exception 'Etapa não encontrada.';
  end if;

  v_sol := coalesce(v_etapa->'solucao', '{}'::jsonb);
  v_ok := (coalesce(p_resposta, '{}'::jsonb) = v_sol);

  if v_ok then
    return jsonb_build_object(
      'correto', true,
      'mensagem', coalesce(v_etapa->>'msg_ok', 'Trava liberada!'),
      'proxima_etapa', p_etapa + 1,
      'concluido', (p_etapa >= v_total)
    );
  end if;

  return jsonb_build_object(
    'correto', false,
    'mensagem', 'Combinação incorreta. Confiram as pistas do Manual e tentem novamente.'
  );
end;
$$;

grant execute on function public.jogo_aventura_carregar(text) to anon, authenticated;
grant execute on function public.jogo_fuga_obter_etapa(text, uuid, text, integer, text) to anon, authenticated;
grant execute on function public.jogo_fuga_validar_trava(text, uuid, text, integer, jsonb) to anon, authenticated;

