------------------------------------------------------------------------------
-- 4) Campanhas codificadas em base64 (zero spoiler no repositório público)
------------------------------------------------------------------------------
insert into public.jogos_campanhas_segredo (id, jogo_id, payload) values
  ('aventura-trem', 'aventura-a-dois', convert_from(decode('', 'base64'), 'UTF8')::jsonb),
  ('aventura-serra', 'aventura-a-dois', convert_from(decode('', 'base64'), 'UTF8')::jsonb),
  ('aventura-deserto', 'aventura-a-dois', convert_from(decode('', 'base64'), 'UTF8')::jsonb),
  ('fuga-observatorio', 'sala-de-fuga', convert_from(decode('', 'base64'), 'UTF8')::jsonb),
  ('fuga-cabine14', 'sala-de-fuga', convert_from(decode('', 'base64'), 'UTF8')::jsonb)
on conflict (id) do update set payload = excluded.payload;
